import{_ as e,o as r,c as a,a6 as o}from"./chunks/framework.DIp0zHSV.js";const g=JSON.parse('{"title":"Alert Mode Lab","description":"The LCARdS Alert Mode Lab: tune how each alert mode recolours your dashboards (hue, strength, saturation, lightness, hue anchors, black alert contrast), preview it, and save it to helpers.","frontmatter":{"description":"The LCARdS Alert Mode Lab: tune how each alert mode recolours your dashboards (hue, strength, saturation, lightness, hue anchors, black alert contrast), preview it, and save it to helpers.","moved_anchors":{"what-it-does":"/configuration/alert-mode-lab","accessing-the-lab":"/configuration/alert-mode-lab#using-the-lab","per-mode-parameters":"/configuration/alert-mode-lab#core-transform-parameters","hsl-parameters":"/configuration/alert-mode-lab#core-transform-parameters","anchor-parameters-red-yellow-blue":"/configuration/alert-mode-lab#hue-anchoring","contrast-parameters-black":"/configuration/alert-mode-lab#contrast-enhancement","live-preview":"/configuration/alert-mode-lab#using-the-lab","saving-settings":"/configuration/alert-mode-lab#using-the-lab"}},"headers":[],"relativePath":"configuration/alert-mode-lab.md","filePath":"configuration/alert-mode-lab.md","lastUpdated":1794184759000}'),s={name:"configuration/alert-mode-lab.md"};function d(l,t,n,h,i,u){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="alert-mode-lab" tabindex="-1">Alert Mode Lab <a class="header-anchor" href="#alert-mode-lab" aria-label="Permalink to &quot;Alert Mode Lab&quot;">​</a></h1><p><strong>The Alert Mode Lab tunes how each alert mode recolours your dashboards, shows the result, and saves it to helpers so it lasts.</strong> It is the first tab of <strong>LCARdS Config &gt; Theme Studio</strong>.</p><ul><li>An alert mode turns every theme colour toward one hue and changes its saturation and lightness. Red, yellow and blue alert also pull colours into a hue band; black alert pushes dark colours darker and light ones lighter.</li><li>Green alert is the baseline (the theme&#39;s own colours) and has nothing to tune.</li><li><a href="./../core/alert-mode.html">Alert Mode</a> explains what alert mode does and how to raise it.</li></ul><div class="tip custom-block"><p class="custom-block-title">Prerequisites</p><p><strong>Save to helpers</strong> needs the Alert Mode Lab helpers. Click <strong>Create All</strong> in the <a href="./#helpers">Helpers tab</a> first.</p></div><hr><h2 id="using-the-lab" tabindex="-1">Using the Lab <a class="header-anchor" href="#using-the-lab" aria-label="Permalink to &quot;Using the Lab&quot;">​</a></h2><p><strong>Pick a mode, move the sliders, apply it to see it, then save.</strong></p><ul><li><strong>Alert mode</strong> picks the mode to tune. With <strong>Apply the mode when selected</strong> on, choosing a mode also applies it.</li><li><strong>Apply Live</strong> applies the mode with the Lab&#39;s current values in this browser, so you can open a dashboard and look. It does not change <code>input_select.lcards_alert_mode</code> or other browsers.</li><li><strong>Reset</strong> puts the mode&#39;s sliders back to their built-in values. <strong>Save to helpers</strong> writes them to the mode&#39;s <a href="./persistent-helpers.html#alert-mode-lab-parameters">helpers</a>; every browser uses the saved values the next time that mode is raised.</li><li>The right side has three views: <strong>Live Preview</strong> (key LCARS colours in the mode), <strong>HSL Wheel</strong> (how each colour moves; circles are green alert, squares the selected mode) and <strong>Full Comparison</strong> (every LCARS colour variable, before and after).</li></ul><hr><h2 id="core-transform-parameters" tabindex="-1">Core Transform Parameters <a class="header-anchor" href="#core-transform-parameters" aria-label="Permalink to &quot;Core Transform Parameters&quot;">​</a></h2><p><strong>The four sliders every mode has: the hue colours turn toward, how far they turn, and how saturated and light they are.</strong></p><table tabindex="0"><thead><tr><th>Slider</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><strong>Hue Target</strong></td><td>0 to 360°</td><td>The hue every colour is turned toward</td></tr><tr><td><strong>Hue Strength</strong></td><td>0 to 1</td><td>How far colours turn: <code>0</code> leaves hues alone, <code>1</code> turns them all the way</td></tr><tr><td><strong>Saturation</strong></td><td>0 to 3×</td><td>Multiplies saturation: below 1 is more muted, above 1 more vivid</td></tr><tr><td><strong>Lightness</strong></td><td>0 to 2×</td><td>Multiplies lightness: below 1 is darker, above 1 brighter</td></tr></tbody></table><h2 id="hue-anchoring" tabindex="-1">Hue Anchoring <a class="header-anchor" href="#hue-anchoring" aria-label="Permalink to &quot;Hue Anchoring&quot;">​</a></h2><p><strong>Red, yellow and blue alert also pull colours into a band of hues, so the whole palette reads as one colour family.</strong> Colours already near the band move little; the rest are pulled in.</p><table tabindex="0"><thead><tr><th>Slider</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><strong>Center Hue</strong></td><td>0 to 360°</td><td>Centre of the band</td></tr><tr><td><strong>Range</strong></td><td>0 to 180°</td><td>How far the band reaches either side of the centre</td></tr><tr><td><strong>Pull Strength</strong></td><td>0 to 1</td><td>How strongly colours are pulled into the band</td></tr></tbody></table><h2 id="contrast-enhancement" tabindex="-1">Contrast Enhancement <a class="header-anchor" href="#contrast-enhancement" aria-label="Permalink to &quot;Contrast Enhancement&quot;">​</a></h2><p><strong>Black alert splits colours at a lightness threshold: colours below it get darker and colours above it get lighter, which keeps text readable on a near-black screen.</strong></p><table tabindex="0"><thead><tr><th>Slider</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><strong>Threshold</strong></td><td>0 to 100%</td><td>The lightness that splits dark colours from light ones</td></tr><tr><td><strong>Dark Multiplier</strong></td><td>0 to 1</td><td>Multiplies the lightness of colours below the threshold</td></tr><tr><td><strong>Light Multiplier</strong></td><td>1 to 2</td><td>Multiplies the lightness of colours above the threshold</td></tr></tbody></table><hr><h2 id="defaults" tabindex="-1">Defaults <a class="header-anchor" href="#defaults" aria-label="Permalink to &quot;Defaults&quot;">​</a></h2><p><strong>The values each mode starts with: what its helpers are created with, and what LCARdS uses when they are missing.</strong> Saturation and lightness are shown as multipliers here; the helpers store them as percentages (<code>1.4</code> is <code>140</code>).</p><table tabindex="0"><thead><tr><th>Mode</th><th>Hue Target</th><th>Hue Strength</th><th>Saturation</th><th>Lightness</th><th>Anchor (centre, range, strength)</th><th>Contrast (threshold, dark, light)</th></tr></thead><tbody><tr><td>Red</td><td>0°</td><td>0.8</td><td>1.4×</td><td>0.9×</td><td>0°, 60°, 0.9</td><td>-</td></tr><tr><td>Yellow</td><td>45°</td><td>0.9</td><td>1.5×</td><td>1.05×</td><td>45°, 50°, 0.9</td><td>-</td></tr><tr><td>Blue</td><td>210°</td><td>0.85</td><td>1.5×</td><td>1.0×</td><td>210°, 70°, 0.85</td><td>-</td></tr><tr><td>Gray</td><td>0°</td><td>0</td><td>0×</td><td>1.0×</td><td>-</td><td>-</td></tr><tr><td>Black</td><td>0°</td><td>0</td><td>0×</td><td>0.7×</td><td>-</td><td>69%, 0.6, 1.0</td></tr></tbody></table><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../core/alert-mode.html">Alert Mode</a>: how alert mode works, how to raise it, and how cards respond</li><li><a href="./persistent-helpers.html#alert-mode-lab-parameters">Persistent Helpers</a>: the helper behind each slider</li><li><a href="./sounds.html">Sound Configuration</a>: the sound each alert mode plays</li></ul>',25)])])}const b=e(s,[["render",d]]);export{g as __pageData,b as default};
